-- Ward General ￿ffe2￿ff80￿ff94 READ-ONLY load: unit census board.
-- Mirrors the app Home page (ops.vBedCensus). No writes.
SET NOCOUNT ON;
DECLARE @Unit NVARCHAR(100) = (SELECT TOP 1 UnitName FROM ops.vBedCensus ORDER BY NEWID());
SELECT UnitName, BedNumber, BedStatus, EncounterId, PatientId, MRN, PatientName, AttendingProvider, AdmitTime
FROM ops.vBedCensus
WHERE (@Unit IS NULL OR UnitName = @Unit)
  AND EncounterId IS NOT NULL
ORDER BY UnitName, BedNumber;

-- Ward General ￿ffe2￿ff80￿ff94 READ-ONLY load: open a patient chart.
-- Mirrors the app bedside chart (clinical.GetPatientChart) for a random active
-- encounter. The heaviest read in the app (all chart sections). No writes.
SET NOCOUNT ON;
DECLARE @EncounterId INT =
    (SELECT TOP 1 EncounterId FROM clinical.Encounter WHERE Status = N'Active' ORDER BY NEWID());
IF @EncounterId IS NOT NULL
    EXEC clinical.GetPatientChart @EncounterId = @EncounterId;

-- Ward General ￿ffe2￿ff80￿ff94 READ-ONLY load: the worklist.
-- Mirrors the app's encounter search (clinical.SearchEncounters), active only.
-- All filters are optional (OPPO). No writes.
SET NOCOUNT ON;
EXEC clinical.SearchEncounters @Status = N'Active';

